#!/usr/bin/env python3
"""Inference on the llamafactory dual-GPU tracer adapter.

Loads base Qwen3-0.6B + the H4-new-data adapter (kg-tracer-lf-adapter, dataset
idalextan/kg-tracer-lf-adapter), merges, and single-shot infers on the 10
embedded tracer-eval passages with the derived STUDENT_PROMPT (thinking OFF,
sampling temp 0.7 / top_p 0.95 / rep 1.15). Writes predictions.jsonl +
raw_<id>.txt. Train and serve use the SAME H4 prompt (ADR-0001 invariant).

Usage on Kaggle: python /kaggle/src/script.py  (metadata in kernel_infer/)
"""

import json
